@startuml

class WebPortal {
  +versionNumber : string
  +urlAddress : string
}

class Building {
  +id : string
  +name : string
  +energyClass : string
  +address : string
  +yearOfConstruction : int
}

class AdditionalEntry {
  +name : string
  +isPublic : boolean
}

class TextualEntry extends AdditionalEntry {}

class NumericalEntry extends AdditionalEntry {
  +value : float
  +unit : string
}

class Image {
  +fileName : string
}

class User {
  +userName : string
  +emailAddress : string
  +password : string
}

class Administrator extends User {
  +idCardNumber : string
}

class Comment {
}

User "1" -- "*" Building : owns
Building "1" -- "*" AdditionalEntry : has
Building "1" -- "*" Image : has
Building "1" -- "1" Image : profile photo
WebPortal "1" -- "*" Building : provides
WebPortal "1" -- "*" User : has
User "1" -- "*" Comment : writes
Building "1" -- "*" Comment : has

@enduml

